+// Sum integer line cents first, then apply the percentage discount once and
+// round the discounted total a single time. Rounding per line inflates totals
+// whenever a discount makes individual lines land on a half-cent boundary
+// (e.g. two 1c lines at 50% must total 1c, not 2c).
+export function totalCents(lines, discountPercent) {
+  const subtotalCents = lines.reduce(
+    (sum, line) => sum + Math.round(line.cents * line.quantity),
+    0,
+  );
+
+  return Math.round(subtotalCents * (1 - discountPercent / 100));
+}
