+/**
+ * Number of items per page used when a caller does not supply a page size.
+ * @type {number}
+ */
 export const defaultPageSize = 20;
+
+/**
+ * Reports whether a value is a finite, whole number greater than zero.
+ *
+ * @param {unknown} value
+ * @returns {boolean}
+ */
+function isPositiveInteger(value) {
+  return typeof value === 'number' && Number.isInteger(value) && value > 0;
+}
+
+/**
+ * @param {unknown} value
+ * @param {string} label
+ * @throws {RangeError} when `value` is not a positive integer.
+ */
+function assertPositiveInteger(value, label) {
+  if (!isPositiveInteger(value)) {
+    throw new RangeError(
+      `${label} must be a positive integer, received ${String(value)}`,
+    );
+  }
+}
+
+/**
+ * Returns a single one-based page of `items` without mutating the input.
+ *
+ * @param {ArrayLike<unknown>} items Source collection; never modified.
+ * @param {number} page One-based page number.
+ * @param {number} pageSize Number of items per page.
+ * @returns {{items: unknown[], total: number, pageCount: number}} A fresh array
+ *   holding the requested slice (empty when the page starts past the end),
+ *   the total item count, and the total number of pages (`0` when empty).
+ * @throws {RangeError} when `page` or `pageSize` is not a positive integer.
+ * @throws {TypeError} when `items` is nullish or has no numeric `length`.
+ */
+export function paginate(items, page, pageSize) {
+  assertPositiveInteger(page, 'page');
+  assertPositiveInteger(pageSize, 'pageSize');
+
+  if (items === null || items === undefined || typeof items.length !== 'number') {
+    throw new TypeError('items must be an array or array-like collection');
+  }
+
+  const total = items.length;
+  const start = (page - 1) * pageSize;
+  const end = start + pageSize;
+
+  // slice() always allocates a new array, so callers can mutate the result
+  // without affecting the source collection.
+  return {
+    items: Array.prototype.slice.call(items, start, end),
+    total,
+    pageCount: Math.ceil(total / pageSize),
+  };
+}
